/// Writes a pack of cases as a Dart source file. Packs are code, not
/// assets, so a broken case fails a test instead of failing on a phone.
library;

import '../engine/case_text.dart';
import '../engine/model.dart';
import 'gen_config.dart';

String packFileName(Tier tier) => 'cases_${tier.name}.dart';

String packVariable(Tier tier) => '${tier.name}Cases';

String renderPack(Tier tier, List<CaseDef> cases) {
  final b = StringBuffer()
    ..writeln(
      '// GENERATED by `dart run tool/generate_cases.dart` - '
      'do not edit by hand.',
    )
    ..writeln('//')
    ..writeln(
      '// The ${tier.name} pack. Each entry is one case in the text '
      'format of',
    )
    ..writeln(
      '// docs/Levels.md, with its certified solution. The slots '
      'and seeds that',
    )
    ..writeln('// produce this file are in lib/gen/gen_campaign.dart.')
    ..writeln()
    ..writeln('const List<String> ${packVariable(tier)} = <String>[');
  for (final c in cases) {
    b
      ..writeln("  '''")
      ..write(writeCase(c))
      ..writeln("''',");
  }
  b.writeln('];');
  return b.toString();
}
